// astro/src/lib/cmsImage.ts
//
// Look up an original Strapi CMS body-image URL in the build-time manifest
// generated by `scripts/fetch-cms-images.mjs`. The manifest is committed so
// production builds always have a consistent lookup, even on cold CI where
// the prebuild fetch may legitimately skip a URL (e.g., transient Strapi
// outage). When the lookup misses, callers fall back to the original URL.

import manifestData from './cmsImageManifest.json';

export interface CmsImageEntry {
  src: string;
  srcset: string;
  width: number;
  height: number;
}

const manifest = manifestData as Record<string, CmsImageEntry>;

export function getCmsImage(url: string): CmsImageEntry | null {
  return manifest[url] ?? null;
}
